<script lang="ts" module>import type{Snippet}from'svelte';import type{RxColor}from'$lib/registry/lib/color';import type{ButtonProps}from'../button/button.svelte';export interface SplitButtonProps{label:string;color?:RxColor;variant?:ButtonProps['variant'];disabled?:boolean;loading?:boolean;onclick?:(event:MouseEvent)=>void;menu:Snippet;icon?:Snippet}</script>
